/* eslint no-compare-neg-zero: "error" */
if (x === 0) {
 // doSomething()...
}
```

 Open in Playground

```
/* eslint no-compare-neg-zero: "error" */
if (Object.is(x, -0)) {
 // doSomething()...
}
```

