## Rule Details

Examples of **incorrect** code for this rule:

```
/*eslint no-unassigned-vars: "error"*/
let ;
if (status === 'ready') {
 console.log('Ready!');
}
let ;
greet(user);
function test() {
 let ;
 return error || "Unknown error";
}
let ;
const { debug } = options || {};
let ;
while (!flag) {
 // Do something...
}
let ;
function init() {
 return config?.enabled;
}
```
In TypeScript:

```
/*eslint no-unassigned-vars: "error"*/
let ;
console.log(value);
```
Examples of **correct** code for this rule:

```
/*eslint no-unassigned-vars: "error"*/
let message = "hello";
console.log(message);
let user;
user = getUser();
console.log(user.name);
let count;
count = 1;
count++;
// Variable is unused (should be reported by `no-unused-vars` only)
let temp;
let error;
if (somethingWentWrong) {
 error = "Something went wrong";
}
console.log(error);
let item;
for (item of items) {
 process(item);
}
let config;
function setup() {
 config = { debug: true };
}
setup();
console.log(config);
let one = undefined;
if (one === two) {
 // Noop
}
```
In TypeScript:

```
/*eslint no-unassigned-vars: "error"*/
declare let value: number | undefined;
console.log(value);
declare module "my-module" {
 let value: string;
 export = value;
}
```

