fn main() {}
use std::collections::VecDeque;
type Link<T> = Option<Box<Node<T>>>;
struct Node<T> {
 elem: T,
 left: Link<T>,
 right: Link<T>,
}
pub struct Tree<T> {
 root: Link<T>,
}
struct NodeIterMut<'a, T: 'a> {
 elem: Option<&'a mut T>,
 left: Option<&'a mut Node<T>>,
 right: Option<&'a mut Node<T>>,
}
enum State<'a, T: 'a> {
 Elem(&'a mut T),
 Node(&'a mut Node<T>),
