# The Final Code

```
use std::alloc::{self, Layout};
use std::marker::PhantomData;
use std::mem;
use std::ops::{Deref, DerefMut};
use std::ptr::{self, NonNull};
struct RawVec<T> {
 ptr: NonNull<T>,
 cap: usize,
}
unsafe impl<T: Send> Send for RawVec<T> {}
unsafe impl<T: Sync> Sync for RawVec<T> {}
impl<T> RawVec<T> {
 fn new() -> Self {
 // !0 is usize::MAX. This branch should be stripped at compile time.
 let cap = if mem::size_of::<T>() == 0 { !0 } else { 0 };
 // `NonNull::dangling()` doubles as "unallocated" and "zero-sized allocation"
 RawVec {
 ptr: NonNull::dangling(),
 cap,
 }
 }
 fn grow(&mut self) {
 // since we set the capacity to usize::MAX when T has size 0,
 // getting to here necessarily means the Vec is overfull.
 assert!(mem::size_of::<T>() != 0, "capacity overflow");
 let (new_cap, new_layout) = if self.cap == 0 {
 (1, Layout::array::<T>(1))
 } else {
 // This can't overflow since self.cap <= isize::MAX.
 let new_cap = 2 * self.cap;
 (new_cap, Layout::array::<T>(new_cap))
 };
 // `Layout::array` checks that the number of bytes allocated is
 // in 1..=isize::MAX and will error otherwise. An allocation of
 // 0 bytes isn't possible thanks to the above condition.
 let new_layout = new_layout.expect("Allocation too large");
 let new_ptr = if self.cap == 0 {
 unsafe { alloc::alloc(new_layout) }
 } else {
 let old_layout = Layout::array::<T>(self.cap).unwrap();
 let old_ptr = self.ptr.as_ptr() as *mut u8;
 unsafe { alloc::realloc(old_ptr, old_layout, new_layout.size()) }
 };
 // If allocation fails, `new_ptr` will be null, in which case we abort.
 self.ptr = match NonNull::new(new_ptr as *mut T) {
 Some(p) => p,
 None => alloc::handle_alloc_error(new_layout),
 };
 self.cap = new_cap;
 }
}
impl<T> Drop for RawVec<T> {
 fn drop(&mut self) {
 let elem_size = mem::size_of::<T>();
 if self.cap != 0 && elem_size != 0 {
 unsafe {
 alloc::dealloc(
 self.ptr.as_ptr() as *mut u8,
 Layout::array::<T>(self.cap).unwrap(),
 );
 }
 }
 }
}
pub struct Vec<T> {
 buf: RawVec<T>,
 len: usize,
}
impl<T> Vec<T> {
 fn ptr(&self) -> *mut T {
 self.buf.ptr.as_ptr()
 }
 fn cap(&self) -> usize {
 self.buf.cap
 }
 pub fn new() -> Self {
 Vec {
 buf: RawVec::new(),
 len: 0,
 }
 }
 pub fn push(&mut self, elem: T) {
 if self.len == self.cap() {
 self.buf.grow();
 }
 unsafe {
 ptr::write(self.ptr().add(self.len), elem);
 }
 // Can't overflow, we'll OOM first.
 self.len += 1;
 }
 pub fn pop(&mut self) -> Option<T> {
 if self.len == 0 {
 None
 } else {
 self.len -= 1;
 unsafe { Some(ptr::read(self.ptr().add(self.len))) }
 }
 }
 pub fn insert(&mut self, index: usize, elem: T) {
 assert!(index <= self.len, "index out of bounds");
 if self.len == self.cap() {
 self.buf.grow();
 }
 unsafe {
 ptr::copy(
 self.ptr().add(index),
 self.ptr().add(index + 1),
 self.len - index,
 );
 ptr::write(self.ptr().add(index), elem);
 }
 self.len += 1;
 }
 pub fn remove(&mut self, index: usize) -> T {
 assert!(index < self.len, "index out of bounds");
 self.len -= 1;
 unsafe {
 let result = ptr::read(self.ptr().add(index));
 ptr::copy(
 self.ptr().add(index + 1),
 self.ptr().add(index),
 self.len - index,
 );
 result
 }
 }
 pub fn drain(&mut self) -> Drain<T> {
 let iter = unsafe { RawValIter::new(&self) };
 // this is a mem::forget safety thing. If Drain is forgotten, we just
 // leak the whole Vec's contents. Also we need to do this *eventually*
 // anyway, so why not do it now?
 self.len = 0;
 Drain {
 iter,
 vec: PhantomData,
 }
 }
}
impl<T> Drop for Vec<T> {
 fn drop(&mut self) {
 while let Some(_) = self.pop() {}
 // deallocation is handled by RawVec
 }
}
impl<T> Deref for Vec<T> {
 type Target = [T];
 fn deref(&self) -> &[T] {
 unsafe { std::slice::from_raw_parts(self.ptr(), self.len) }
 }
}
impl<T> DerefMut for Vec<T> {
 fn deref_mut(&mut self) -> &mut [T] {
 unsafe { std::slice::from_raw_parts_mut(self.ptr(), self.len) }
 }
}
impl<T> IntoIterator for Vec<T> {
 type Item = T;
 type IntoIter = IntoIter<T>;
 fn into_iter(self) -> IntoIter<T> {
 let (iter, buf) = unsafe {
 (RawValIter::new(&self), ptr::read(&self.buf))
 };
 mem::forget(self);
 IntoIter {
 iter,
 _buf: buf,
 }
 }
}
struct RawValIter<T> {
 start: *const T,
 end: *const T,
}
impl<T> RawValIter<T> {
